-- ============================================================
-- SalesPlace — جدول عروض ودعومات المشاريع (project_support_offers)
-- جدول جديد بالكامل — لا يمسّ أي دالة أو جدول موجود حالياً
-- شغّل هذا الملف كاملاً مرة واحدة في Supabase SQL editor
-- ============================================================

create table if not exists project_support_offers (
  id bigint generated always as identity primary key,
  project_id integer,                    -- يطابق id المشروع بالكتالوج داخل التطبيق، فارغ لو المشروع خارج الـ187 المتاحة بالداشبورد
  project_name text not null,            -- الاسم كما ورد بملف المميزات (قد يختلف عن اسم الكتالوج الكامل)
  project_code text,
  destination text,
  sector text,
  land_type text,
  developer text,
  city text,
  status text,                           -- حالة المشروع (متاح، إلخ)
  developer_kind text,                   -- NHC / مطور خاص
  beneficiary_scope text,                -- مستفيدين / مستفيدين وغير مستفيدين / غير مستفيدين
  units_unsold integer,
  units_total integer,
  price_max numeric,
  price_avg numeric,
  price_min numeric,
  redf_support_category text,            -- دعم الصندوق (150,000): مستفيدين / لا ينطبق / ...
  dara_plus_category text,               -- ذرى بلس (120,000): نعم / لا ينطبق
  mod_support_category text,             -- دعم وزارة الدفاع
  in_kind_category text,                 -- دعم عيني: ينطبق / لا ينطبق
  infra_support_category text,           -- أعلى قيمة دعم بنية تحتية (رقم أو "لا ينطبق")
  phase_discount_category text,          -- خصم المرحلة الأولى
  discounts_text text,                   -- خصومات (نص وصفي)
  cashback_text text,                    -- كاش باك (نص وصفي)
  ac_text text,                          -- مكيفات
  kitchen_text text,                     -- مطابخ
  furniture_text text,                   -- أثاث
  booking_fee_discount_text text,        -- خصم على رسوم الحجز
  flexible_installment_text text,        -- القسط المرن (نطاق ونسب)
  updated_at timestamptz not null default now()
);

create unique index if not exists project_support_offers_name_uk on project_support_offers (project_name);
create index if not exists project_support_offers_pid_idx on project_support_offers (project_id);

alter table project_support_offers enable row level security;

-- قراءة عامة (نفس نمط unit_status المتاح للجميع بالمفتاح العام الحالي)
drop policy if exists project_support_offers_read on project_support_offers;
create policy project_support_offers_read on project_support_offers
  for select using (true);

-- الكتابة فقط عبر دالة إدارية (نفس نمط admin_sync_unit_status / admin_upsert_allocation_mirror
-- الموجودتين حالياً — تتحقق من app_users بنفسها بدل الاعتماد على Supabase Auth)
create or replace function admin_upsert_project_offers(p_admin text, p_pass text, p_rows jsonb)
returns jsonb
language plpgsql
security definer
as $$
declare
  v_ok boolean;
  v_admin boolean;
begin
  select true, coalesce(is_admin,false) into v_ok, v_admin
  from app_users
  where username = p_admin and password = p_pass and coalesce(is_active,true)
  limit 1;

  if v_ok is not true then
    return jsonb_build_object('ok', false, 'msg', 'بيانات دخول غير صحيحة');
  end if;
  if v_admin is not true then
    return jsonb_build_object('ok', false, 'msg', 'هذا الإجراء يتطلب صلاحية مدير');
  end if;

  insert into project_support_offers (
    project_id, project_name, project_code, destination, sector, land_type, developer, city,
    status, developer_kind, beneficiary_scope, units_unsold, units_total, price_max, price_avg,
    price_min, redf_support_category, dara_plus_category, mod_support_category, in_kind_category,
    infra_support_category, phase_discount_category, discounts_text, cashback_text, ac_text,
    kitchen_text, furniture_text, booking_fee_discount_text, flexible_installment_text, updated_at
  )
  select
    (r->>'project_id')::integer, r->>'project_name', r->>'project_code', r->>'destination',
    r->>'sector', r->>'land_type', r->>'developer', r->>'city', r->>'status', r->>'developer_kind',
    r->>'beneficiary_scope', (r->>'units_unsold')::integer, (r->>'units_total')::integer,
    (r->>'price_max')::numeric, (r->>'price_avg')::numeric, (r->>'price_min')::numeric,
    r->>'redf_support_category', r->>'dara_plus_category', r->>'mod_support_category',
    r->>'in_kind_category', r->>'infra_support_category', r->>'phase_discount_category',
    r->>'discounts_text', r->>'cashback_text', r->>'ac_text', r->>'kitchen_text',
    r->>'furniture_text', r->>'booking_fee_discount_text', r->>'flexible_installment_text', now()
  from jsonb_array_elements(p_rows) as r
  on conflict (project_name) do update set
    project_id = excluded.project_id, project_code = excluded.project_code,
    destination = excluded.destination, sector = excluded.sector, land_type = excluded.land_type,
    developer = excluded.developer, city = excluded.city, status = excluded.status,
    developer_kind = excluded.developer_kind, beneficiary_scope = excluded.beneficiary_scope,
    units_unsold = excluded.units_unsold, units_total = excluded.units_total,
    price_max = excluded.price_max, price_avg = excluded.price_avg, price_min = excluded.price_min,
    redf_support_category = excluded.redf_support_category, dara_plus_category = excluded.dara_plus_category,
    mod_support_category = excluded.mod_support_category, in_kind_category = excluded.in_kind_category,
    infra_support_category = excluded.infra_support_category, phase_discount_category = excluded.phase_discount_category,
    discounts_text = excluded.discounts_text, cashback_text = excluded.cashback_text, ac_text = excluded.ac_text,
    kitchen_text = excluded.kitchen_text, furniture_text = excluded.furniture_text,
    booking_fee_discount_text = excluded.booking_fee_discount_text,
    flexible_installment_text = excluded.flexible_installment_text, updated_at = now();

  return jsonb_build_object('ok', true, 'msg', 'تم التحديث');
end;
$$;

